"""Checks how your tests are organized. Do not edit this file.

Tests are code too: pytest can list them (--collect-only) and the fixtures they
can use (--fixtures) without running them, and the configuration is a file
anyone can read. That is what these checks do.
"""

import ast
import os
import subprocess
import sys
import tomllib
from pathlib import Path

LAB = Path(__file__).resolve().parent.parent
TEST_FILES = ["tests/test_cart.py", "tests/test_discount.py"]
FIXTURES = ["catalog", "cart", "almost_discount"]


def pytest_output(*args: str) -> str:
    env = {**os.environ, "PYTHONIOENCODING": "utf-8"}
    env.pop("CART_MUTANT", None)
    result = subprocess.run(
        [sys.executable, "-m", "pytest", *TEST_FILES, "-q", "-p", "no:cacheprovider", *args],
        cwd=LAB, env=env, capture_output=True, text=True, encoding="utf-8", errors="replace",
    )
    return result.stdout


def pytest_table() -> dict:
    return tomllib.loads((LAB / "pyproject.toml").read_text(encoding="utf-8")).get("tool", {}).get("pytest", {})


# Task 1


def test_the_tests_do_not_build_their_own_cart():
    for name in TEST_FILES:
        tree = ast.parse((LAB / name).read_text(encoding="utf-8"))
        for test in ast.walk(tree):
            if not (isinstance(test, ast.FunctionDef) and test.name.startswith("test_")):
                continue
            for call in ast.walk(test):
                if isinstance(call, ast.Call) and getattr(call.func, "id", None) in ("Catalog", "Cart"):
                    raise AssertionError(
                        f"{name}::{test.name} still builds {call.func.id}(...): "
                        "move that preparation into a fixture and ask for it as a parameter"
                    )


# Task 2


def test_the_fixtures_are_shared_from_conftest():
    listing = {}
    for line in pytest_output("--fixtures").splitlines():
        name, separator, location = line.partition(" -- ")
        if separator:
            listing[name.strip()] = location
    for fixture in FIXTURES:
        assert fixture in listing, f"There is no fixture named '{fixture}'"
        assert "conftest.py" in listing[fixture], (
            f"The fixture '{fixture}' is defined in {listing[fixture]}: move it to tests/conftest.py "
            "so every test file can use it"
        )


# Task 3


def test_the_slow_marker_is_registered():
    markers = pytest_table().get("markers", [])
    assert any(marker.split(":")[0].strip() == "slow" for marker in markers), (
        "Register the 'slow' marker in [tool.pytest] markers"
    )


def test_the_slow_test_is_marked():
    selected = [line for line in pytest_output("--collect-only", "-m", "slow").splitlines() if "::" in line]
    assert any("test_many_additions_add_up" in line for line in selected), (
        "Mark test_many_additions_add_up with @pytest.mark.slow"
    )
